'use strict';
/**
 * Storage analyzer: measures real disk usage per category and proposes safe
 * cleanups. Only data that is temporary or generated by the manager is ever
 * offered for cleanup, and only with explicit user action (or an explicitly
 * configured retention policy). Saves are never cleaned.
 */
const fsp = require('node:fs/promises');
const path = require('node:path');
const layout = require('../server/layout');
const { dirSize, diskSpace, exists, safeRemove } = require('../core/fsutil');
const { AppError } = require('../core/util');

class Storage {
  constructor(ctx) { this.ctx = ctx; this.last = null; }

  async _size(p) { return (await exists(p)) ? dirSize(p) : { bytes: 0, files: 0 }; }

  async analyze() {
    const P = this.ctx.paths;
    const servers = [];
    for (const srv of this.ctx.registry.list()) {
      const install = await this._size(srv.installDir);
      const mods = await this._size(layout.modsDir(srv.installDir));
      const logs = await this._size(layout.logsDir(srv.installDir));
      const crashes = await this._size(layout.crashesDir(srv.installDir));
      let temp = 0;
      for (const d of layout.steamTempDirs(srv.installDir)) temp += (await this._size(d)).bytes;
      const backups = await this._size(path.join(this.ctx.backups.root(), srv.id));
      const saves = await this._size(layout.sessionSaveDir(this.ctx.backups.saveRoot(srv)));
      const runLogs = await this._size(path.join(P.runs, srv.id));
      const diag = await this._size(path.join(P.diagnostics, srv.id));
      const snaps = await this._size(path.join(P.modSnapshots, srv.id));
      const rollback = await this._size(path.join(P.rollback, srv.id));
      const disk = await diskSpace(srv.installDir).catch(() => null);
      servers.push({
        id: srv.id, name: srv.name, disk,
        categories: [
          { key: 'server', label: 'Server files', bytes: install.bytes - mods.bytes - logs.bytes - crashes.bytes - temp },
          { key: 'mods', label: 'Mods', bytes: mods.bytes },
          { key: 'saves', label: 'Saves', bytes: saves.bytes },
          { key: 'backups', label: 'Backups', bytes: backups.bytes },
          { key: 'logs', label: 'Logs', bytes: logs.bytes + runLogs.bytes },
          { key: 'crashes', label: 'Crash dumps & diagnostics', bytes: crashes.bytes + diag.bytes },
          { key: 'temp', label: 'Temporary installation files', bytes: temp },
          { key: 'snapshots', label: 'Mod & rollback snapshots', bytes: snaps.bytes + rollback.bytes },
        ],
      });
    }
    const steamcmd = await this._size(P.steamcmd);
    const app = await this._size(P.userData);
    this.last = { at: Date.now(), servers, steamcmd: steamcmd.bytes, managerData: app.bytes, recommendations: await this.recommendations(servers) };
    return this.last;
  }

  async recommendations(servers) {
    const out = [];
    for (const s of servers) {
      const temp = s.categories.find((c) => c.key === 'temp');
      if (temp.bytes > 50 * 1024 ** 2 && !this.ctx.supervisor.status(s.id).busy) out.push({ id: `temp:${s.id}`, serverId: s.id, label: `Remove leftover Steam download data (${s.name})`, bytes: temp.bytes, action: 'steam-temp', safe: true, detail: 'Partial downloads from interrupted updates. SteamCMD recreates what it needs.' });
      const crashes = s.categories.find((c) => c.key === 'crashes');
      if (crashes.bytes > 100 * 1024 ** 2) out.push({ id: `crashes:${s.id}`, serverId: s.id, label: `Delete old crash dumps (${s.name})`, bytes: crashes.bytes, action: 'crash-dumps', safe: true, detail: 'Crash dumps older than 14 days. Crash history entries are kept.' });
      const logs = s.categories.find((c) => c.key === 'logs');
      if (logs.bytes > 200 * 1024 ** 2) out.push({ id: `logs:${s.id}`, serverId: s.id, label: `Delete console logs older than 30 days (${s.name})`, bytes: null, action: 'old-logs', safe: true, detail: 'Per-run console logs and rotated FactoryGame logs older than 30 days.' });
      const backups = s.categories.find((c) => c.key === 'backups');
      if (backups.bytes > 5 * 1024 ** 3 && !this.ctx.settings.get('backups').retentionEnabled) out.push({ id: `retention:${s.id}`, serverId: s.id, label: `Backups use ${(backups.bytes / 1024 ** 3).toFixed(1)} GB (${s.name})`, bytes: backups.bytes, action: 'configure-retention', safe: true, detail: 'No retention policy is configured. Enable one in Settings → Backups to keep disk usage under control. Backups are never deleted automatically without it.' });
    }
    if (await exists(this.ctx.paths.temp)) {
      const t = await dirSize(this.ctx.paths.temp);
      if (t.bytes > 10 * 1024 ** 2 && !this.ctx.setup.abort) out.push({ id: 'manager-temp', label: 'Clear manager temporary folder', bytes: t.bytes, action: 'manager-temp', safe: true, detail: 'Leftover downloads from interrupted operations.' });
    }
    return out;
  }

  async _deleteOlder(dir, maxAgeMs, filter = () => true) {
    let freed = 0;
    for (const e of await fsp.readdir(dir, { withFileTypes: true }).catch(() => [])) {
      const p = path.join(dir, e.name);
      const st = await fsp.stat(p).catch(() => null);
      if (!st || Date.now() - st.mtimeMs < maxAgeMs || !filter(e.name)) continue;
      const size = e.isDirectory() ? (await dirSize(p)).bytes : st.size;
      await safeRemove(p, [dir]);
      freed += size;
    }
    return freed;
  }

  async cleanup(recId, { confirm = false, actor = 'local' } = {}) {
    if (!confirm) throw new AppError('E_CONFIRM_REQUIRED', 'Cleanup requires confirmation.');
    const rec = (this.last ? this.last.recommendations : []).find((r) => r.id === recId);
    if (!rec) throw new AppError('E_NOT_FOUND', 'Run the analysis again before cleaning up.');
    let freed = 0;
    const srv = rec.serverId ? this.ctx.registry.get(rec.serverId) : null;
    if (srv && (this.ctx.supervisor.status(srv.id).busy || (rec.action === 'steam-temp' && this.ctx.steamcmd.busy))) throw new AppError('E_BUSY', 'The server is busy; try again after the current operation.');
    switch (rec.action) {
      case 'steam-temp': for (const d of layout.steamTempDirs(srv.installDir)) if (await exists(d)) { freed += (await dirSize(d)).bytes; await safeRemove(d, [path.join(srv.installDir, 'steamapps')]); } break;
      case 'crash-dumps': freed += await this._deleteOlder(layout.crashesDir(srv.installDir), 14 * 86400000); freed += await this._deleteOlder(path.join(this.ctx.paths.diagnostics, srv.id), 14 * 86400000); break;
      case 'old-logs': freed += await this._deleteOlder(path.join(this.ctx.paths.runs, srv.id), 30 * 86400000, (n) => n.endsWith('.log')); freed += await this._deleteOlder(layout.logsDir(srv.installDir), 30 * 86400000, (n) => /-backup-.*\.log$/i.test(n)); break;
      case 'manager-temp': freed += await this._deleteOlder(this.ctx.paths.temp, 0); break;
      case 'configure-retention': return { freed: 0, navigate: 'settings/backups' };
      default: throw new AppError('E_VALIDATION', 'Unknown cleanup');
    }
    this.ctx.audit.record({ actor, action: 'storage.cleanup', serverId: rec.serverId || null, target: rec.label, details: { freedBytes: freed } });
    return { freed };
  }

  /** Retention-driven cleanup, only for policies the user configured. */
  async applyPolicies() {
    const st = this.ctx.settings.get('storage');
    let freed = 0;
    for (const srv of this.ctx.registry.list()) {
      if (st.logRetentionDays > 0) freed += await this._deleteOlder(path.join(this.ctx.paths.runs, srv.id), st.logRetentionDays * 86400000, (n) => n.endsWith('.log'));
      if (st.diagnosticsRetentionDays > 0) freed += await this._deleteOlder(path.join(this.ctx.paths.diagnostics, srv.id), st.diagnosticsRetentionDays * 86400000);
      await this.ctx.backups.applyRetention(srv.id);
    }
    this.ctx.notifications.prune();
    return { message: `Retention policies applied${freed ? `, ${(freed / 1048576).toFixed(0)} MB freed` : ''}` };
  }
}

module.exports = { Storage };
